rows=[]
for x in prior:
 if x['status']=='complete top five':continue
 key=x['pm_id']+'|'+x['substance_id'];rs=[r for r in rels if r['pm']==x['pm_id']and r['substance_id']==x['substance_id']and r['dietary_input']is True];assert rs,key
 sid=x['substance_id'];status='unresolved research gap';reason=x['reason'];action=x['next_action'];rank=True
 if sid in non:status='legitimately non-rankable for the recorded ordinary-food relationship';reason=non[sid];action='Retain source/protocol evidence without ordinary-food top-five requirement.';rank=False
 if key=='BRS5-FM2-PM4|arabinan':status='legitimately non-rankable for the recorded ordinary-food relationship';reason='Canonical input is pea-fibre arabinan in the tested preparation. Apple cell-wall arabinan cannot stand in for this material.';action='Only preparation-matched pea-fibre composition may support the existing record. Broader food equivalence would need separate scientific review.';rank=False
 if key=='BRS5-FM2-PM4|pectin':status='legitimately non-rankable for the recorded ordinary-food relationship';reason='Canonical input is specifically citrus pectin. Four general-food total-pectic measurements do not establish the admitted citrus material.';action='Remove these four edges from the local qualified ranking; retain original food observations and PM admission.';rank=False
 if key=='BRS6-FM1-PM3|resistant-starch':status='legitimately non-rankable for the recorded ordinary-food relationship';reason='PM owns protocol-specific resistant-starch modulation, with positive and null trial results. Food concentration cannot establish tested formulation or effective dose.';action='Retain supplemental protocol; food composition may remain contextual but not an equivalent top-five intervention list.';rank=False
 if sid=='glucose':status='legitimately non-rankable for the recorded ordinary-food relationship';reason='PM owns a luminal glucose sensory stimulus in a mouse circuit, not a nutritional requirement. Highest-glucose foods are not an evidence-based optimisation ranking.';action='Keep two food observations; omit the target from nutritional top-five completeness and scoring. Admission unchanged.';rank=False
 if sid=='l-carnitine':status='completed';reason='Unscoped pending creatine/CoQ reviews incorrectly held all beef supplementary observations. Add their existing row keys, preserving both pending decisions. Independently sourced free-L-carnitine now qualifies.';action='Rank five source-specific foods; retain original preparation and repeated-extraction uncertainty.'
 if sid=='phosphatidylcholine':status='completed';reason='Both PMs explicitly own choline provision from PC. Ranking measured PC-derived choline moiety is appropriate to that relationship, with original units explicit. Do not require an invented intact-PC molecular mass.';action='Five highest verified foods in the extracted seven-food source pool; separate analytical basis, no conversion or total-choline substitution.'
 if sid in ['cysteine','glutamate','glutamine']:reason='Canonical role does not impose a free-amino-acid-only food requirement. Earlier free-only wording was too restrictive. Protein-bound evidence may be relevant, but assays and delivery evidence still need verification; cystine is not silently renamed cysteine and hydrolytic Glx is not split.';action='Resolve form-specific food measurements against this provision relationship; preserve estimates as estimates. No new precursor admission is made.'
 if sid in ['flavin-mononucleotide','pyridoxal-5-phosphate']:reason+=' The biological cofactor record must not automatically inherit the precursor vitamin food quantities. Clarification of an upstream provision mapping is a separate proposal, not a missing-data substitution.'
 if sid=='nicotinamide-riboside':reason='Existing milk research is informative in its original micromoles/L basis. Requiring conversion to 100g is unnecessary for displaying evidence; however, generic whole milk is not the tested skim preparation, and a comparable multi-food ranking is not established.';action='Retain exact skim-milk observation in source evidence; resolve canonical preparation mapping and compare only like denominators. Do not manufacture density.'
 if sid=='epicatechin':reason='PM owns epicatechin provision rather than one cocoa formulation. The limitation is food preparation identity, not a need for intact cocoa to duplicate a clinical protocol.';action='Verify source-specific nonalkalised cocoa mapping and other same-analyte foods; do not relabel raw cacao or extrapolate to other catechins.'
 rows.append({'pm_id':x['pm_id'],'substance_id':sid,'disposition':status,'ordinary_food_rank_eligible':rank,'previous_selected_foods':int(x['after']),'reason':reason,'next_action':action,'canonical_records':[r['source_record']for r in rs],'canonical_input':[r['input']for r in rs],'biological_role':[r['biological_role']for r in rs],'canonical_classification':[r['relationship_type']for r in rs],'canonical_limitations':[r['limitation']for r in rs],'prior_research_source':x['source']})
json.dump(rows,open(R/'target-reconciliation.json','w'),indent=2)
with open(R/'target-reconciliation.csv','w')as f:
 w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows([{k:json.dumps(v,ensure_ascii=False)if isinstance(v,(list,dict))else v for k,v in r.items()}for r in rows])
